def solve(g):
    from collections import Counter
    h,w=len(g),len(g[0])
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    seen=[[False]*w for _ in range(h)]; cis=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]!=bg and not seen[i][j]:
                c=g[i][j]; st=[(i,j)]; seen[i][j]=True; cells=[]
                while st:
                    y,x=st.pop(); cells.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<h and 0<=nx<w and g[ny][nx]==c and not seen[ny][nx]:
                                seen[ny][nx]=True; st.append((ny,nx))
                rs=[y for y,_ in cells]; cs=[x for _,x in cells]
                nrm=tuple(sorted((y-min(rs),x-min(cs)) for y,x in cells))
                cis.append((c,len(cells),(min(rs),min(cs)),nrm))
    # pick component whose color appears most often among components (d1: 8). For test tie -> ?
    cnt=Counter(c for c,_,_,_ in cis)
    best=max(cnt.items(),key=lambda kv:kv[1])[0]
    comps_best=[(s,at,nrm) for c,s,at,nrm in cis if c==best]
    # among those with largest size? d2: best=7 has sizes [5,9,14,7,11,4]; largest 14. But output uses 5! 
    return cnt,cis
