def solve(shapes,cover,tgt,H,W):
    if cover>=tgt: return cover==tgt
    rem=tgt-cover
    # choose smallest shape that can touch rem
    s=min(shapes,key=lambda s:len(s&rem))
    shapes=set(shapes)
    used=set()
    if s is None:
        return False
    res=[]; _solve([],{s},res); 
    return res
def _solve(curr,used,shapes_avail,res):
    if len(used)==len(shapes_avail) or not shapes_avail:
        res.append(dict(zip(range(len(shapes_avail)),set(used))))
        return
    # pick an unused shape with coverage potential
    rem=set(tgt)-set(used)
    for si,s in enumerate(shapes_avail):
        if s in used: continue
        best=max((ay for ay in range(H) for ax in range(W) if all(0<=ay+y<H and 0<=ax+x<W for y,x in s) and {(ay+y,ax+x) for y,x in s}&rem),default=None)
        if best is None: continue
        moved={(best[0]+y,best[1]+x) for y,x in s}
        if moved & used: continue
        used|={moved}; _solve([curr]+[si],used,shapes_avail-{s},res);
        if res: return
